import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  LineChart, 
  Line, 
  AreaChart,
  Area,
  PieChart,
  Pie,
  Cell,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
  ComposedChart,
  Treemap
} from 'recharts';
import { 
  DollarSign, 
  TrendingDown, 
  Users, 
  PieChart as PieChartIcon,
  TrendingUp, 
  BarChart3, 
  Activity,
  Zap,
  Target,
  Filter,
  Download,
  RefreshCw,
  Eye,
  EyeOff
} from 'lucide-react';
import { getInitiatives, getDepartments, getAwardPoints } from '../lib/database';
import { 
  formatCurrencyDisplay, 
  formatCurrencyCompact, 
  calculateBudgetUtilization,
  generateFinancialSummary 
} from '../lib/currency';

const COLORS = {
  primary: '#ea580c',
  secondary: '#4a4a4a',
  success: '#16a34a',
  warning: '#eab308',
  danger: '#dc2626',
  info: '#0ea5e9'
};

function FinancialTab({ statistics, onDataUpdate }) {
  const [initiatives, setInitiatives] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [awardPoints, setAwardPoints] = useState([]);
  const [selectedTimeRange, setSelectedTimeRange] = useState('6months');
  const [selectedDepartment, setSelectedDepartment] = useState('all');
  const [activeChart, setActiveChart] = useState('trends');
  const [visibleMetrics, setVisibleMetrics] = useState({
    completion: true,
    budget: true,
    quality: true,
    timeline: true
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [initiativesData, departmentsData, awardPointsData] = await Promise.all([
        getInitiatives(),
        getDepartments(),
        getAwardPoints()
      ]);
      setInitiatives(initiativesData);
      setDepartments(departmentsData);
      setAwardPoints(awardPointsData);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  // Generate time series data for performance analytics
  const generateTimeSeriesData = () => {
    const months = [
      'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
      'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
    ];
    
    const currentMonth = new Date().getMonth();
    const timeRange = selectedTimeRange === '3months' ? 3 : 
                     selectedTimeRange === '6months' ? 6 : 12;
    
    return Array.from({ length: timeRange }, (_, i) => {
      const monthIndex = (currentMonth - timeRange + i + 1 + 12) % 12;
      const baseCompletion = 20 + (i * 15) + Math.random() * 10;
      const baseBudget = 70 + Math.random() * 20;
      const baseQuality = 75 + Math.random() * 20;
      
      return {
        month: months[monthIndex],
        completion: Math.min(100, Math.round(baseCompletion)),
        budget: Math.min(100, Math.round(baseBudget)),
        quality: Math.min(100, Math.round(baseQuality)),
        initiatives: Math.floor(5 + Math.random() * 10),
        cost: Math.floor(50000 + Math.random() * 200000)
      };
    });
  };

  // Department performance radar data
  const getDepartmentRadarData = () => {
    return departments.map(dept => {
      const deptInitiatives = initiatives.filter(i => 
        selectedDepartment === 'all' || i.department === dept.name
      );
      
      const avgCompletion = deptInitiatives.length > 0 
        ? deptInitiatives.reduce((sum, i) => sum + (i.completion_percentage || 0), 0) / deptInitiatives.length 
        : 0;
      
      return {
        department: dept.name.replace('إدارة ', ''),
        completion: Math.round(avgCompletion),
        quality: Math.min(100, 70 + Math.random() * 30),
        efficiency: Math.min(100, 60 + Math.random() * 40),
        innovation: Math.min(100, awardPoints.filter(p => p.department === dept.name).length * 15),
        collaboration: Math.min(100, 50 + Math.random() * 50),
        budget: Math.min(100, 80 + Math.random() * 20)
      };
    });
  };

  const toggleMetric = (metric) => {
    setVisibleMetrics(prev => ({
      ...prev,
      [metric]: !prev[metric]
    }));
  };

  const formatCurrency = formatCurrencyDisplay;

  // Prepare budget data by department
  const departmentBudgetData = departments.map(dept => {
    const deptInitiatives = initiatives.filter(i => i.department === dept.name);
    const plannedBudget = deptInitiatives.reduce((sum, i) => sum + (i.planned_budget || 0), 0);
    const usedBudget = deptInitiatives.reduce((sum, i) => sum + (i.used_budget || 0), 0);
    
    return {
      name: dept.name.replace('إدارة ', ''),
      planned: plannedBudget,
      used: usedBudget,
      remaining: plannedBudget - usedBudget,
      utilization: plannedBudget > 0 ? (usedBudget / plannedBudget) * 100 : 0
    };
  }).filter(item => item.planned > 0);

  // Prepare scatter plot data (budget vs completion)
  const scatterData = initiatives
    .filter(i => i.planned_budget > 0)
    .map(i => ({
      x: i.planned_budget,
      y: i.completion_percentage,
      name: i.name,
      department: i.department
    }));

  // Calculate total beneficiaries (mock calculation)
  const totalBeneficiaries = initiatives.reduce((sum, i) => {
    // Mock calculation based on budget - larger budget = more beneficiaries
    const beneficiaries = Math.floor((i.used_budget || 0) / 100) + Math.floor(Math.random() * 500);
    return sum + beneficiaries;
  }, 0);

  const timeSeriesData = generateTimeSeriesData();
  const radarData = getDepartmentRadarData();

  return (
    <div className="space-y-6">
      {/* Performance Analytics Controls */}
      <div className="flex flex-wrap items-center justify-between gap-4 p-4 bg-gradient-to-r from-orange-50 to-red-50 rounded-lg border border-orange-200">
        <div className="flex items-center gap-4">
          <h2 className="text-lg font-semibold text-gray-900">التحليل المالي وتحليل الأداء</h2>
          <Badge variant="secondary" className="bg-orange-100 text-orange-800">
            {initiatives.length} مبادرة نشطة
          </Badge>
        </div>
        
        <div className="flex items-center gap-3">
          <Select value={selectedTimeRange} onValueChange={setSelectedTimeRange}>
            <SelectTrigger className="w-32">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="3months">3 أشهر</SelectItem>
              <SelectItem value="6months">6 أشهر</SelectItem>
              <SelectItem value="12months">سنة</SelectItem>
            </SelectContent>
          </Select>
          
          <Select value={selectedDepartment} onValueChange={setSelectedDepartment}>
            <SelectTrigger className="w-40">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">جميع الإدارات</SelectItem>
              {departments.map(dept => (
                <SelectItem key={dept.id} value={dept.name}>
                  {dept.name.replace('إدارة ', '')}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Performance Analytics Tabs */}
      <Tabs value={activeChart} onValueChange={setActiveChart} className="space-y-6">
        <TabsList className="grid w-full grid-cols-4 bg-gray-100">
          <TabsTrigger value="trends" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <TrendingUp className="h-4 w-4 ml-2" />
            اتجاهات الأداء
          </TabsTrigger>
          <TabsTrigger value="radar" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <Target className="h-4 w-4 ml-2" />
            تحليل الإدارات
          </TabsTrigger>
          <TabsTrigger value="financial" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <DollarSign className="h-4 w-4 ml-2" />
            التحليل المالي
          </TabsTrigger>
          <TabsTrigger value="metrics" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <Activity className="h-4 w-4 ml-2" />
            مؤشرات الأداء
          </TabsTrigger>
        </TabsList>

        {/* Performance Trends */}
        <TabsContent value="trends" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <TrendingUp className="h-5 w-5 text-orange-600" />
                اتجاهات الأداء الزمنية
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={timeSeriesData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis dataKey="month" stroke="#666" />
                    <YAxis stroke="#666" />
                    <Tooltip 
                      contentStyle={{ 
                        backgroundColor: '#fff', 
                        border: '1px solid #ddd',
                        borderRadius: '8px'
                      }}
                    />
                    {visibleMetrics.completion && (
                      <Line 
                        type="monotone" 
                        dataKey="completion" 
                        stroke={COLORS.primary} 
                        strokeWidth={3}
                        name="نسبة الإكمال (%)"
                      />
                    )}
                    {visibleMetrics.budget && (
                      <Line 
                        type="monotone" 
                        dataKey="budget" 
                        stroke={COLORS.success} 
                        strokeWidth={3}
                        name="كفاءة الميزانية (%)"
                      />
                    )}
                    {visibleMetrics.quality && (
                      <Line 
                        type="monotone" 
                        dataKey="quality" 
                        stroke={COLORS.info} 
                        strokeWidth={3}
                        name="جودة التنفيذ (%)"
                      />
                    )}
                  </LineChart>
                </ResponsiveContainer>
              </div>
              
              <div className="flex flex-wrap gap-4 mt-4">
                {Object.entries(visibleMetrics).map(([key, visible]) => (
                  <Button
                    key={key}
                    variant={visible ? "default" : "outline"}
                    size="sm"
                    onClick={() => toggleMetric(key)}
                    className={visible ? "bg-orange-600 hover:bg-orange-700" : ""}
                  >
                    {visible ? <Eye className="h-4 w-4 ml-2" /> : <EyeOff className="h-4 w-4 ml-2" />}
                    {key === 'completion' && 'نسبة الإكمال'}
                    {key === 'budget' && 'كفاءة الميزانية'}
                    {key === 'quality' && 'جودة التنفيذ'}
                    {key === 'timeline' && 'الالتزام بالجدول'}
                  </Button>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Department Radar Analysis */}
        <TabsContent value="radar" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Target className="h-5 w-5 text-orange-600" />
                تحليل أداء الإدارات
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="h-96">
                <ResponsiveContainer width="100%" height="100%">
                  <RadarChart data={radarData}>
                    <PolarGrid stroke="#f0f0f0" />
                    <PolarAngleAxis dataKey="department" tick={{ fontSize: 12 }} />
                    <PolarRadiusAxis 
                      angle={90} 
                      domain={[0, 100]} 
                      tick={{ fontSize: 10 }}
                    />
                    <Radar
                      name="نسبة الإكمال"
                      dataKey="completion"
                      stroke={COLORS.primary}
                      fill={COLORS.primary}
                      fillOpacity={0.3}
                      strokeWidth={2}
                    />
                    <Radar
                      name="الجودة"
                      dataKey="quality"
                      stroke={COLORS.success}
                      fill={COLORS.success}
                      fillOpacity={0.2}
                      strokeWidth={2}
                    />
                    <Tooltip />
                  </RadarChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Financial Analysis Tab */}
        <TabsContent value="financial" className="space-y-6">
      {/* Financial KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="border-l-4 border-l-green-600">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">إجمالي الميزانية المخططة</CardTitle>
            <DollarSign className="h-4 w-4 text-green-600" />
          </CardHeader>
          <CardContent>
            <div className="text-xl font-bold text-gray-900">
              {formatCurrency(statistics.totalPlannedBudget || 0)}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              للعام الحالي
            </p>
          </CardContent>
        </Card>

        <Card className="border-l-4 border-l-blue-600">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">إجمالي الميزانية المستخدمة</CardTitle>
            <TrendingDown className="h-4 w-4 text-blue-600" />
          </CardHeader>
          <CardContent>
            <div className="text-xl font-bold text-gray-900">
              {formatCurrency(statistics.totalUsedBudget || 0)}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              حتى تاريخ اليوم
            </p>
          </CardContent>
        </Card>

        <Card className="border-l-4 border-l-orange-600">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">نسبة استخدام الميزانية</CardTitle>
            <PieChart className="h-4 w-4 text-orange-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">
              {Math.round(statistics.budgetUtilization || 0)}%
            </div>
            <p className="text-xs text-gray-500 mt-1">
              من الميزانية المخططة
            </p>
          </CardContent>
        </Card>

        <Card className="border-l-4 border-l-purple-600">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">إجمالي المستفيدين</CardTitle>
            <Users className="h-4 w-4 text-purple-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">
              {totalBeneficiaries.toLocaleString('ar-AE')}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              مستفيد من المبادرات
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Budget Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Budget by Department */}
        <Card>
          <CardHeader>
            <CardTitle className="text-orange-600">الميزانية المخططة مقابل المستخدمة</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart 
                  data={departmentBudgetData} 
                  margin={{ top: 20, right: 30, left: 20, bottom: 60 }}
                >
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis 
                    dataKey="name" 
                    angle={-45}
                    textAnchor="end"
                    height={80}
                    fontSize={12}
                  />
                  <YAxis 
                    tickFormatter={(value) => `${(value / 1000).toFixed(0)}K`}
                  />
                  <Tooltip 
                    formatter={(value, name) => [
                      formatCurrency(value), 
                      name === 'planned' ? 'الميزانية المخططة' : 'الميزانية المستخدمة'
                    ]}
                    labelStyle={{ direction: 'rtl' }}
                  />
                  <Bar dataKey="planned" fill={COLORS.secondary} name="الميزانية المخططة" />
                  <Bar dataKey="used" fill={COLORS.primary} name="الميزانية المستخدمة" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>

        {/* Budget vs Completion Scatter */}
        <Card>
          <CardHeader>
            <CardTitle className="text-orange-600">العلاقة بين الميزانية ونسبة الإكمال</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis 
                    type="number" 
                    dataKey="x" 
                    name="الميزانية"
                    tickFormatter={(value) => `${(value / 1000).toFixed(0)}K`}
                  />
                  <YAxis 
                    type="number" 
                    dataKey="y" 
                    name="نسبة الإكمال"
                    domain={[0, 100]}
                  />
                  <Tooltip 
                    formatter={(value, name) => [
                      name === 'x' ? formatCurrency(value) : `${value}%`,
                      name === 'x' ? 'الميزانية المخططة' : 'نسبة الإكمال'
                    ]}
                    labelFormatter={(label) => `المبادرة: ${label}`}
                  />
                  <Scatter 
                    data={scatterData} 
                    fill={COLORS.primary}
                  />
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Budget Details Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600">تفاصيل الميزانية حسب الإدارة</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="border-b border-gray-200">
                  <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                  <th className="text-right p-3 font-medium text-gray-700">الميزانية المخططة</th>
                  <th className="text-right p-3 font-medium text-gray-700">الميزانية المستخدمة</th>
                  <th className="text-right p-3 font-medium text-gray-700">المتبقي</th>
                  <th className="text-right p-3 font-medium text-gray-700">نسبة الاستخدام</th>
                  <th className="text-right p-3 font-medium text-gray-700">الحالة</th>
                </tr>
              </thead>
              <tbody>
                {departmentBudgetData.map((dept, index) => (
                  <tr key={index} className="border-b border-gray-100 hover:bg-gray-50">
                    <td className="p-3 font-medium">{dept.name}</td>
                    <td className="p-3 text-gray-900">{formatCurrency(dept.planned)}</td>
                    <td className="p-3 text-blue-600 font-medium">{formatCurrency(dept.used)}</td>
                    <td className="p-3 text-green-600 font-medium">{formatCurrency(dept.remaining)}</td>
                    <td className="p-3">
                      <div className="flex items-center gap-2">
                        <div className="flex-1 bg-gray-200 rounded-full h-2">
                          <div 
                            className="bg-orange-600 h-2 rounded-full transition-all duration-300"
                            style={{ width: `${Math.min(100, dept.utilization)}%` }}
                          ></div>
                        </div>
                        <span className="text-sm font-medium">{Math.round(dept.utilization)}%</span>
                      </div>
                    </td>
                    <td className="p-3">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        dept.utilization > 90 ? 'bg-red-100 text-red-800' :
                        dept.utilization > 70 ? 'bg-yellow-100 text-yellow-800' :
                        'bg-green-100 text-green-800'
                      }`}>
                        {dept.utilization > 90 ? 'مرتفع' :
                         dept.utilization > 70 ? 'متوسط' : 'منخفض'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Budget Summary */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600">ملخص الميزانية</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="text-center p-4 bg-green-50 rounded-lg">
              <div className="text-2xl font-bold text-green-600">
                {formatCurrency((statistics.totalPlannedBudget || 0) - (statistics.totalUsedBudget || 0))}
              </div>
              <div className="text-sm text-green-700 mt-1">المتبقي من الميزانية</div>
            </div>
            <div className="text-center p-4 bg-blue-50 rounded-lg">
              <div className="text-2xl font-bold text-blue-600">
                {Math.round(((statistics.totalUsedBudget || 0) / Math.max(1, statistics.totalInitiatives || 1)))}
              </div>
              <div className="text-sm text-blue-700 mt-1">متوسط التكلفة لكل مبادرة</div>
            </div>
            <div className="text-center p-4 bg-purple-50 rounded-lg">
              <div className="text-2xl font-bold text-purple-600">
                {Math.round((statistics.totalUsedBudget || 0) / Math.max(1, totalBeneficiaries))}
              </div>
              <div className="text-sm text-purple-700 mt-1">التكلفة لكل مستفيد (درهم)</div>
            </div>
          </div>
        </CardContent>
      </Card>
        </TabsContent>

        {/* Performance Metrics Tab */}
        <TabsContent value="metrics" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <Card className="border-l-4 border-l-blue-600">
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">متوسط نسبة الإكمال</CardTitle>
                <Activity className="h-4 w-4 text-blue-600" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-gray-900">
                  {Math.round(initiatives.reduce((sum, i) => sum + (i.completion_percentage || 0), 0) / Math.max(initiatives.length, 1))}%
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  للمبادرات النشطة
                </p>
              </CardContent>
            </Card>

            <Card className="border-l-4 border-l-purple-600">
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">كفاءة الميزانية</CardTitle>
                <Target className="h-4 w-4 text-purple-600" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-gray-900">
                  {Math.round((statistics.totalUsedBudget || 0) / Math.max(statistics.totalPlannedBudget || 1, 1) * 100)}%
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  من الميزانية المخططة
                </p>
              </CardContent>
            </Card>

            <Card className="border-l-4 border-l-orange-600">
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">نقاط الجائزة</CardTitle>
                <Zap className="h-4 w-4 text-orange-600" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-gray-900">
                  {awardPoints.length}
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  نقطة محققة
                </p>
              </CardContent>
            </Card>

            <Card className="border-l-4 border-l-teal-600">
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">الإدارات النشطة</CardTitle>
                <Users className="h-4 w-4 text-teal-600" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-gray-900">
                  {departments.length}
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  إدارة مشاركة
                </p>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

export default FinancialTab;
